def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

# The greatest value of m for N=10 is achieved when the sequence is 1, 2, ..., 10.
# m = C(10, 3)
m_max = combinations(10, 3)
print(f"The correct maximum value of m for N=10 is: {m_max}")
